function t(e){switch(e){case"active":return{label:"Running",cls:"bg-blue-100 text-blue-700"};case"completed":return{label:"Completed",cls:"bg-emerald-100 text-emerald-700"};case"paused":return{label:"Paused",cls:"bg-amber-100 text-amber-700"};case"draft":return{label:"Draft",cls:"bg-gray-100 text-gray-500"};default:return{label:"Scheduled",cls:"bg-gray-100 text-gray-600"}}}function a(e){return e==="active"?"bg-blue-500":e==="completed"?"bg-emerald-500":e==="paused"?"bg-amber-500":"bg-gray-400"}function l(e,r={day:"numeric",month:"short",year:"numeric"}){return e?new Date(e).toLocaleDateString("en-US",r):null}export{a as d,l as f,t as s};
